-- 0006_shifts: one row per shift on a weekly schedule.
-- Generated by drizzle-kit, then hand-edited:
--   * the schedule's unique key now includes location_id, and is added BEFORE the foreign
--     key that references it (drizzle-kit emitted it last, after the shifts table);
--   * `ON DELETE SET NULL (job_role_id)`: on this two-column key a plain SET NULL would
--     also null org_id, which is NOT NULL (same gotcha as 0005);
--   * the exclusion constraint against double-booking, which drizzle-kit cannot express;
--   * the row-level security section.

CREATE TYPE "public"."shift_status" AS ENUM('open', 'assigned', 'cancelled');--> statement-breakpoint
CREATE TABLE "shifts" (
	"id" uuid PRIMARY KEY NOT NULL,
	"org_id" uuid NOT NULL,
	"schedule_id" uuid NOT NULL,
	"location_id" uuid NOT NULL,
	"job_role_id" uuid,
	"employee_id" uuid,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"break_minutes" integer DEFAULT 0 NOT NULL,
	"status" "shift_status" DEFAULT 'open' NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"notes" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "shifts_org_id_id_unique" UNIQUE("org_id","id"),
	CONSTRAINT "shifts_time_positive" CHECK ("shifts"."ends_at" > "shifts"."starts_at"),
	CONSTRAINT "shifts_break_range" CHECK ("shifts"."break_minutes" between 0 and 240),
	CONSTRAINT "shifts_break_shorter" CHECK ("shifts"."break_minutes" * 60 < extract(epoch from ("shifts"."ends_at" - "shifts"."starts_at"))),
	CONSTRAINT "shifts_status_matches_employee" CHECK (("shifts"."status" = 'assigned' and "shifts"."employee_id" is not null)
          or ("shifts"."status" = 'open' and "shifts"."employee_id" is null)
          or "shifts"."status" = 'cancelled'),
	CONSTRAINT "shifts_version_positive" CHECK ("shifts"."version" >= 1)
);--> statement-breakpoint
-- Hand-edited: moved up from the end so the composite key exists before shifts uses it.
ALTER TABLE "schedules" ADD CONSTRAINT "schedules_org_id_id_location_unique" UNIQUE("org_id","id","location_id");--> statement-breakpoint
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_schedule_fk" FOREIGN KEY ("org_id","schedule_id","location_id") REFERENCES "public"."schedules"("org_id","id","location_id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_employee_same_org_fk" FOREIGN KEY ("org_id","employee_id") REFERENCES "public"."employees"("org_id","id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_job_role_same_org_fk" FOREIGN KEY ("org_id","job_role_id") REFERENCES "public"."job_roles"("org_id","id") ON DELETE SET NULL (job_role_id) ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "shifts_org_schedule_idx" ON "shifts" USING btree ("org_id","schedule_id");--> statement-breakpoint
CREATE INDEX "shifts_org_employee_start_idx" ON "shifts" USING btree ("org_id","employee_id","starts_at");--> statement-breakpoint
CREATE INDEX "shifts_org_location_start_idx" ON "shifts" USING btree ("org_id","location_id","starts_at");--> statement-breakpoint

-- ==================== No double-booking (hand-written) ====================
-- One employee cannot be in two places at once, across every location in the org. The
-- database enforces it, so two managers (or a retried request) can never both win; the
-- service checks first only to answer with a friendly error. Open and cancelled shifts are
-- outside the index: they have nobody on them.
ALTER TABLE shifts ADD CONSTRAINT shifts_no_double_booking
  EXCLUDE USING gist (employee_id WITH =, tstzrange(starts_at, ends_at) WITH &&)
  WHERE (status = 'assigned');--> statement-breakpoint

-- ===================== Row-level security (hand-written) =====================
ALTER TABLE shifts ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE shifts FORCE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY tenant_isolation ON shifts
  USING (org_id = current_org_id())
  WITH CHECK (org_id = current_org_id());
